def test_load_json_replayjournalrecord():
    json_data = r'''
    {
      "kind": "session"
    }
    '''
    data = json.loads(json_data, strict=False)
    instance = ReplayJournalRecord.load(data)
    assert instance is not None
    assert instance.kind == "session"

def test_load_yaml_replayjournalrecord():
    yaml_data = r'''
    kind: session

    '''
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = ReplayJournalRecord.load(data)
    assert instance is not None
    assert instance.kind == "session"

def test_roundtrip_json_replayjournalrecord():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r'''
    {
      "kind": "session"
    }
    '''
    original_data = json.loads(json_data, strict=False)
    instance = ReplayJournalRecord.load(original_data)
    saved_data = instance.save()
    reloaded = ReplayJournalRecord.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "session"

def test_to_json_replayjournalrecord():
    """Test that to_json produces valid JSON."""
